<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){fwrite(STDERR,"CLI only.\n");exit(2);}
$root=dirname(__DIR__);$config=require $root.'/config/app.php';require $root.'/app/Core/Database.php';
$name=trim((string)($argv[1]??'DCP MCP client'));$requested=trim((string)($argv[2]??'platform.read,terminal.safe-read'));$allowed=['platform.read','terminal.safe-read','terminal.execute','filesystem.read','filesystem.write','filesystem.delete','cloud.status.read','cloud.pairing.manage','cloud.connection.manage','cloud.connection.read','process.read','process.terminate','sensitive.read','task.create','memory.read'];$scopes=array_values(array_unique(array_filter(array_map('trim',explode(',',$requested)),fn($s)=>in_array($s,$allowed,true))));if($name===''||strlen($name)>120||$scopes===[]){fwrite(STDERR,"Usage: php platform/bin/mcp-token.php <name> [platform.read,terminal.safe-read,terminal.execute,filesystem.read,filesystem.write,filesystem.delete,cloud.status.read,cloud.pairing.manage,cloud.connection.manage,cloud.connection.read,process.read,process.terminate,sensitive.read,task.create,memory.read]\nAt least one valid scope is required.\n");exit(2);}
$db=Database::connect($config);Database::migrate($db);$token=bin2hex(random_bytes(32));$id='mcp_'.bin2hex(random_bytes(10));$q=$db->prepare('INSERT INTO mcp_tokens(id,name,token_hash,scopes_json,created_at) VALUES(?,?,?,?,?)');$q->execute([$id,$name,hash('sha256',$token),json_encode($scopes,JSON_THROW_ON_ERROR),date(DATE_ATOM)]);echo "DCP MCP token created. Copy it now; it will not be shown again.\nID: {$id}\nName: {$name}\nScopes: ".implode(', ',$scopes)."\nBearer token: {$token}\nEndpoint: http://127.0.0.1:<DCP_PORT>/mcp\n";
